import re, pathlib
report = pathlib.Path('/tmp/REPORT-final.md').read_text()
BARE = re.compile(r'-?\d+\.\d+')
SRC = re.compile(r'-?\d+(?:\.\d+)?\s*\(P(\d+)\)')
BAND = re.compile(r'\[\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*\]')
issues = 0
for i, line in enumerate(report.split('\n'), 1):
    masked = BAND.sub('', line)
    if not SRC.search(masked) and BARE.search(masked):
        print("BARE DECIMAL line", i, ":", line); issues += 1
    for m in re.finditer(r'H\d+', line):
        if m.group(0) not in {'H1','H2','H3','H4','H5','H6'}:
            print("UNKNOWN H line", i, m.group(0)); issues += 1
# sourced numbers reconcile check
rec = {'P1':10.5,'P2':35.5,'P3':8,'P4':9,'P5':21,'P6':30}
for i, line in enumerate(report.split('\n'), 1):
    masked = BAND.sub('', line)
    for m in SRC.finditer(masked):
        val = float(re.match(r'-?\d+(?:\.\d+)?', m.group(0)).group(0))
        pid = 'P'+m.group(1)
        if pid not in rec:
            print("UNKNOWN PID line", i, pid); issues += 1
        elif abs(val - rec[pid]) > max(0.01*abs(rec[pid]), 1e-9):
            print("MISMATCH line", i, val, pid); issues += 1
print("issues:", issues)

subs = await rlm.list_subagents()
for s in subs:
    if s.session_name == 'grill-H5':
        await rlm.delete_subagent(s)
        print("deleted", s.session_name)
